package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Shared address normalization for the owner create pipeline. An address is normalized by
 * trimming and collapsing internal runs of whitespace to a single space, upper-casing, and
 * expanding common street-type abbreviations token-by-token ({@code ST -> STREET},
 * {@code RD -> ROAD}, {@code AVE -> AVENUE}). So {@code "  12  main  st "} becomes
 * {@code "12 MAIN STREET"} and {@code "7 elm ave"} becomes {@code "7 ELM AVENUE"}.
 *
 * <p>The normalized value is what {@code POST /api/owners} stores and returns as {@code address},
 * and it is the form every address comparison (household duplicate detection and the shared
 * household id) is done against. Normalization is idempotent: normalizing an already-normalized
 * address yields the same value.
 */
final class OwnerAddress {

    /** Whole-token abbreviations expanded to their full street type. */
    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET",
            "RD", "ROAD",
            "AVE", "AVENUE");

    private OwnerAddress() {
    }

    /**
     * Normalizes an address. A {@code null} input is left as {@code null}; an input that is empty
     * or only whitespace normalizes to {@code ""} (which the required-field check treats as blank).
     */
    static String normalize(String input) {
        if (input == null) {
            return null;
        }
        String collapsed = input.trim().replaceAll("\\s+", " ");
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return sb.toString();
    }

    /** The normalized address, with {@code null} mapped to {@code ""} for safe comparison. */
    static String normalizeForCompare(String input) {
        String normalized = normalize(input);
        return normalized == null ? "" : normalized;
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;
import java.util.regex.Pattern;

import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
import org.springframework.samples.petclinic.util.Localities;

/**
 * Shared postcode validation for the owner create/update pipelines. Postcode is optional; when a
 * request carries one it must be exactly 4 digits and, for a city with a known region, fall within
 * that region's fixed range. A city with no known region (locality {@code "UNKNOWN"}) accepts any
 * 4-digit postcode. The postcode is stored and returned exactly as given.
 */
final class OwnerPostcode {

    /** A postcode must be exactly 4 digits. */
    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");

    /** Region -> inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_RANGE = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    private OwnerPostcode() {
    }

    /**
     * Validates the postcode on the request. An absent (null) postcode is left untouched. A present
     * postcode must be 4 digits and, when the city's region is known, within that region's range.
     *
     * @throws InvalidPostcodeException when a postcode is present but malformed or out of range for
     *         the city's region.
     */
    static void validate(OwnerFieldsDto request) throws InvalidPostcodeException {
        String postcode = request.getPostcode();
        if (postcode == null) {
            return;
        }
        if (!FOUR_DIGITS.matcher(postcode).matches()) {
            throw new InvalidPostcodeException(postcode);
        }
        int[] range = REGION_RANGE.get(Localities.localityFor(request.getCity()));
        if (range == null) {
            return; // no known region: any 4-digit postcode is accepted
        }
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidPostcodeException(postcode);
        }
    }
}

